/**
 * Static UI message catalogues for the Baladi municipal platform.
 * Every key MUST exist in every language; unknown keys fall back to English,
 * and a missing English value falls back to the raw key.
 *
 * Convention: dotted keys grouped by feature, lowercase.
 * Placeholders: `{name}`-style tokens; pass values to t(key, { name }).
 *
 * USER-CONTENT names (municipality / department / category / role) are NOT here —
 * those use per-row Arabic/French DB fields via `pickName(item, locale)`.
 */
